"use client"

import * as React from "react"
import { Progress as ProgressPrimitive } from "@base-ui/react/progress"

import { cn } from "@/lib/utils"

// Leather Luxe Progress: recessed track, cognac leather fill with sheen.
// Base UI's Progress.Indicator computes the fill width from the value, so the
// manual translateX is dropped in favour of the primitive's own sizing.

const Progress = React.forwardRef<
  HTMLDivElement,
  Omit<ProgressPrimitive.Root.Props, "value"> & {
    value?: ProgressPrimitive.Root.Props["value"]
  }
>(({ className, value, ...props }, ref) => (
  <ProgressPrimitive.Root
    ref={ref}
    value={value ?? null}
    className={cn(
      "relative h-2.5 w-full overflow-hidden rounded-full",
      "border border-border bg-well [box-shadow:var(--shadow-well)]",
      className
    )}
    {...props}
  >
    <ProgressPrimitive.Track className="h-full w-full">
      <ProgressPrimitive.Indicator
        className={cn(
          "h-full rounded-full",
          "[background-image:var(--gradient-leather)]",
          "[box-shadow:inset_0_0.0625rem_0_oklch(1_0_0/0.25),inset_0_-0.0625rem_0.125rem_oklch(0_0_0/0.3)]",
          "transition-[width] duration-slow ease-out"
        )}
      />
    </ProgressPrimitive.Track>
  </ProgressPrimitive.Root>
))
Progress.displayName = "Progress"

export { Progress }
